整理来源：Nginx转发gRPC.md、Nginx开启双向验证.md、错误.md
主题：Nginx 转发 gRPC 流量（HTTP 层 + SNI 分流）+ 双向 TLS 认证证书生成与配置一、Nginx 转发 gRPCgRPC 配置参考文档：https://www.54benniao.com/a/759.html
证书生成参考本文「二、Nginx 开启双向验证」。1.1 接收 grpcs 转发 grpc（HTTP 层）监听 7100 端口（SSL + HTTP/2），客户端证书验证后通过 grpc_pass 转发到上游 gRPC 服务器集群。worker_processes auto;

events {
  worker_connections  1024;
}

http {
  # ===== 缓冲区（代理用户头信息）=====
  proxy_buffer_size 1024m;          # 保存用户头信息的缓冲区大小
  proxy_buffers 4 1024m;            # proxy_buffers 缓冲区
  proxy_busy_buffers_size 2048m;    # 繁忙缓冲区，建议为单块 proxy_buffers 的 2 倍，满则写磁盘临时文件

  # ===== 请求体/超时 =====
  client_max_body_size 4096m;       # 请求体大小上限，超过返回 413
  client_header_timeout 7d;         # 读取请求头超时，超过返回 408
  client_body_timeout 7d;           # 读取请求体超时

  # ===== 长连接 keepalive =====
  keepalive_timeout 7d;             # keep-alive 连接保持时长（默认 75s，0 禁用）
  keepalive_requests 4294967295;    # 单连接最大请求数（默认 100）

  upstream grpc_servers {
    server Proxy节点服务器1IP:7001;
    server Proxy节点服务器2IP:7001;
    keepalive 2000;                 # 每个 worker 进程缓存的上游空闲 keep-alive 连接数（超出按 LRU 关闭）
  }

  server {
    listen 7100 ssl http2;

    ssl_certificate      /data/app/nginx_certs/server.crt;   # 服务端证书
    ssl_certificate_key  /data/app/nginx_certs/server.key;   # 服务端私钥
    ssl_client_certificate /data/app/nginx_certs/root.crt;   # 根证书（验证客户端）
    ssl_verify_client on;                                    # 启用客户端证书验证

    location / {
      grpc_pass grpc://grpc_servers;                          # 转发给 upstream 中一个
      grpc_set_header Host $host;
      grpc_set_header X-Real-IP $remote_addr;
      grpc_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

      grpc_send_timeout 7d;         # 向 gRPC 服务器传输请求的超时（连续两次写之间）
      grpc_read_timeout 7d;         # 从 gRPC 服务器读取响应的超时（连续两次读之间）
      grpc_socket_keepalive on;     # 为 socket 打开 SO_KEEPALIVE
    }
  }
}1.2 根据 TLS Server Name（SNI）转发（stream 层）不终止 TLS，基于 $ssl_preread_server_name 按域名把 grpcs 流量分流到不同上游（4 层转发，stream 模块）：worker_processes 1;

events {
    worker_connections  1024;
}

stream {
    map $ssl_preread_server_name $targetBackend {
         GT00BDCSSM.node1.org proxy1;
         GT00BDCSSM.node2.org proxy2;
    }

    server {
        listen 7100;
        ssl_preread on;             # 预读 SNI 但不终止 TLS
        proxy_pass $targetBackend;
    }

    upstream proxy1 {
        server 10.5.5.51:7001;
    }
    upstream proxy2 {
        server 10.5.5.61:7001;
    }
}1.3 常见错误排查upstream prematurely closed connection while reading upstream上游服务已关闭连接检查上游 gRPC 服务是否存活、健康检查、keepalive/超时参数是否合理二、Nginx 开启双向验证（mTLS）双向验证（mTLS）：服务端不仅要出示自己的证书，还要验证客户端证书（ssl_verify_client on）。2.1 生成自签名根证书（可选）openssl genrsa -out root.key 2048
openssl req -x509 -new -nodes -key root.key -sha256 -days 3650 -out root.crt -subj "/CN=chainamker.org"2.2 生成服务器私钥和证书# 1. 生成服务器私钥 + CSR
openssl genrsa -out server.key 2048
openssl req -new -key server.key -out server.csr -subj "/CN=server.org"

# 2. 使用自签名根证书签署服务器证书
openssl x509 -req -in server.csr -CA root.crt -CAkey root.key -CAcreateserial -out server.crt -days 3650 -sha2562.3 生成客户端证书# 1. 生成客户端私钥
openssl genrsa -out client.key 2048

# 2. 生成客户端 CSR
openssl req -new -key client.key -out client.csr -subj "/CN=client.org"

# 3a. 使用自签名根证书签署客户端证书
openssl x509 -req -in client.csr -CA root.crt -CAkey root.key -CAcreateserial -out client.crt -days 3650 -sha256

# 3b. 或使用受信任的 CA 签署客户端证书
openssl x509 -req -in client.csr -CA ca.crt -CAkey ca.key -out client.crt -days 3650 -sha2562.4 配置到 Nginxserver {
    listen 443 ssl;
    server_name example.com;

    ssl_certificate      /path/to/server.crt;   # 服务器证书
    ssl_certificate_key  /path/to/server.key;   # 服务器私钥
    ssl_client_certificate /path/to/client.crt; # 客户端证书（验证客户端用）
    ssl_verify_client on;                       # 开启客户端证书验证

    # 其他 SSL 配置项（密码套件、协议等）
}注意：/path/to/ 替换为实际证书路径。若使用受信 CA 签发的证书，ssl_client_certificate 应指向 CA 证书。2.5 传统交互式生成证书流程（备用）生成带密码的密钥 → 去掉密码 → 生成 CSR → 交互填写信息 → 自签名：# 1) 生成 RSA 密钥（需设置并记住密码）
openssl genrsa -des3 -out domain.key 1024

# 2) 拷贝一个不需要输入密码的密钥文件
openssl rsa -in domain.key -out domain_nopass.key

# 3) 生成证书请求
openssl req -new -key domain.key -out domain.csr交互输入项（Common Name 必须与网站域名一致）：Enter pass phrase for domain.key之前设置的密码Country Name (2 letter code)CNState or Province NameJilinLocality NameChangchunOrganization NamePythonOrganizational Unit NamePythonCommon Namedomain.com（必须与域名一致）Email Address123@domain.comA challenge password直接回车An optional company name直接回车自签名（不向 CA 申请，用密钥和 CSR 自行签发）：openssl x509 -req -days 365 -in domain.csr -signkey domain.key -out domain.crt三、速查与注意事项3.1 证书文件清单（本文件夹已生成的证书）root.key / root.crt自签名根 CA 私钥 / 根证书root.srlOpenSSL 序列号文件（-CAcreateserial 生成）server.key / server.csr / server.crt服务器私钥 / CSR / 签署后的服务器证书client.key / client.csr / client.crt客户端私钥 / CSR / 签署后的客户端证书3.2 关键指令速查grpc_pass grpc://upstream转发 gRPC 请求到上游grpc_send_timeout / grpc_read_timeoutgRPC 收发超时（连续读写间隔）ssl_preread on + map $ssl_preread_server_name4 层按 SNI 分流，不终止 TLSssl_certificate / ssl_certificate_key服务器证书 / 私钥ssl_client_certificate客户端证书（验证用）ssl_verify_client on开启双向验证（mTLS）keepalive 2000（upstream）上游空闲 keep-alive 连接缓存数3.3 注意事项自签名证书仅适用于开发/测试环境，生产环境应从受信 CA 获取证书双向验证下，客户端必须持有被 ssl_client_certificate 信任的证书，否则握手失败gRPC 必须走 HTTP/2（listen ... http2 或 h2c），普通 HTTP/1.1 无法转发生产环境不建议把 proxy_buffer_size / client_max_body_size 等设成 GB 级，按实际业务压测确定upstream prematurely closed connection 通常表示上游服务已关闭，优先排查上游存活与健康检查整理版本：v1.0 · 2026-08-18

本文档由 4 篇 libp2p 相关笔记合并整理：《libp2p DHT Kademlia 迭代查询》（源码解析，核心）、《2022-01-05 libp2p 分享-明超》（ChainMaker 集成实践）、《2022-02-07 学习 libp2p》（KAD 算法速记，已补全）、《libp2p 遇到的问题》（实战排查）。1. 背景基础：Kademlia 算法与 libp2p1.1 Kademlia 算法核心思想原文速记：KAD 算法（Kademlia）其实是在 chord 上做的优化。主要是两个点：1、用二进制（32/64/128）表示一个节点的 id，两节点的 id 异或运算得到节点间的距离……Kademlia 是 P2P 网络中经典的一致性哈希（DHT）路由算法，相对 Chord 的核心改进如下：距离度量顺时针环上顺时针差值节点 ID 按位异或（XOR）距离性质单向（非对称）对称：dist(A,B) == dist(B,A)，且满足三角不等式路由表finger table（对数级）K 桶（K-bucket），按公共前缀长度分桶节点查找每次跳转距离减半每轮并发查询 alpha 个节点，对数级收敛 + 高并发容错依赖 successor list同一 K 桶存 k 个节点，单点失效不影响K 桶关键规则：节点 ID 用二进制表示（32/64/128 bit 可选），两个 ID 异或运算的结果即节点间"距离"，距离越小越"近"；路由表按公共前缀（XOR 距离的最高位）划分成一组 K 桶（默认每桶最多 k 个节点）；查找目标 key 时，从最近的桶开始，每次取距离最近的 alpha 个节点并发查询，迭代逼近目标；桶中节点按最近活跃时间排序，旧节点被淘汰（LRU），保持路由表新鲜度。1.2 libp2p 简介libp2p 是一个模块化的 P2P 网络协议栈（IPFS 团队发起），提供传输层抽象、身份（Peer ID）、连接管理、流多路复用、节点发现（DHT / mDNS / Gossip）等能力。Go 生态的核心实现为 go-libp2p，其协议接口定义在 go-libp2p-core（第 3 章中 ChainMaker 的国密改造正是围绕这一层展开）。1.3 关键概念速查表bucketSize（k）20K 桶大小，路由表中每桶最大节点数，也是种子 peer 数量alpha10每轮并发查询的节点数（并发度）beta3终止条件：查到 beta 个最近节点即认为查询完成PeerHeard-已听说但未查询的节点（初始状态）PeerWaiting-已发起查询、等待结果中的节点PeerQueried-查询成功的节点（终态）PeerUnreachable-拨号/RPC 失败的节点（终态，移出路由表）LastUsefulAt-路由表中节点"最近有用"时间，用于 MVP 记录与淘汰2. DHT 迭代查询源码解析（核心）2.1 迭代查询概述query 是整个 DHT 的核心，这里称之为迭代查询。DHT routing 中几乎所有方法都调用它，如 FindPeer、FindProviders、GetValue、PutValue、Provide。理解 query 是理解整个 DHT 的关键。入口函数：runLookupWithFollowup(ctx, target, queryFn, stopFn) —— 使用指定查询函数在目标上执行查找，并在上下文被取消或停止函数返回 true 时停止。参数说明：ctxcontext.Context上下文targetstring要查询的目标，可以是 peerid、multihash 等类型的 keyqueryFnqueryFn查询方法参数：func(context.Context, peer.ID) ([]*peer.AddrInfo, error)stopFnstopFn停止函数，查询到符合条件的 peerid 时返回 true返回值：type lookupWithFollowupResult struct {
	peers []peer.ID            // 获得排名前 20 个（DHT K 桶大小）
	state []qpeerset.PeerState // peers 对应的状态

	// indicates that neither the lookup nor the followup has been prematurely terminated by an external condition such
	// as context cancellation or the stop function being called.
	// 查询和后续操作都没有被外部条件（例如：上下文取消或调用的停止函数）提前终止。
	completed bool
}2.2 总体流程（7 步）首先根据 key 值，从本地路由表中获取最近的 k（默认 20）个节点作为种子 peer；再从种子 peer 截取 alpha（默认 10）个 peer，这 alpha 个 peer 称之为查询 peer；每个查询 peer 启动一个 task，发起 rpc 查询请求，发起 rpc 查询请求前会先拨号。每个 task 执行有快有慢，最后会等待所有 task 都执行完。就算把这些查询 peer 都查完可能也不满足循环退出条件（例如：10 个 peer 中 8 个离线、1 个 rpc 查询失败、只有 1 个查询成功，那么需要根据这个查询成功的 peer 去迭代查询）；查询 peer 在某些类型（如 GET_VALUE、GET_PROVIDERS、FIND_NODE）rpc 请求中会把离它最近的 peer 作为响应消息发回（也可以通过 GetClosestPeers 获取最近的节点），这些离查询 peer 最近的 peer 称之为新 peer；一个 peer 可能有多个地址，新 peer 可能已经在本地 peerstore 中，但本地 peerstore 的地址和查询到的新地址可能不一致（本地可能不是最新的），合并它们将这些已知的地址都加入本地 peerstore（下次迭代查询发起 rpc 查询前会先拨号，拨号需要地址）；将这些新 peer 发回到 chan，这时新 peer 转换成查询 peer，准备第二次查询。最外面的循环里首先会对查询 peer 的状态进行更新，再对状态为 PeerHeard 的新 peer 继续启动 task，发起 rpc 查询请求。依次反复直到满足退出条件，整个迭代查询结束；将排序后的结果返回。迭代查询退出条件（3 个）：stopFn调用者通过闭包传入，如 GetClosestPeers 始终返回 falseisLookupTermination查到了 beta（默认 3）个 peerisStarvationTermination没有 peer 可查（饥饿）2.3 时序图原始配图：watermark,type_ZmFuZ3poZW5naGVpdGk,...t_70.png（CSDN 博文截图）配图内容描述：该图为 DHT Kademlia 迭代查询的时序图，展示了一次完整 lookup 的调用链：调用方 → runLookupWithFollowup → runQuery → query.run（内部循环：updateState → isReadyToTerminate → spawnQuery 迭代）→ 对每个查询 peer 先 dialPeer 拨号、再 queryFn 发 RPC → 收到新 peer 后合并地址、继续下一轮迭代 → 满足退出条件（beta 个已查询 / 无 peer 可查 / stopFn）后 terminate → 排序返回 top-K 结果。以下用 Mermaid 重绘等价时序：sequenceDiagram
    autonumber
    participant Caller as 调用方(FindPeer等)
    participant DHT as IpfsDHT
    participant RT as 本地路由表
    participant Q as query 对象
    participant P as 查询peer(alpha个并发)

    Caller->>DHT: runLookupWithFollowup(ctx, target, queryFn, stopFn)
    DHT->>RT: NearestPeers(targetKadID, bucketSize=20)
    RT-->>DHT: 返回 20 个种子peer
    DHT->>Q: 构造 query 对象并 q.run()
    Note over Q: 种子peer以 heard 状态入 QueryPeerset
    loop 迭代循环
        Q->>Q: updateState(更新各peer状态)
        Q->>Q: isReadyToTerminate(alpha - NumWaiting)
        alt 满足退出条件
            Q->>Q: terminate(cancelPath)
        else 未满足
            Q->>P: spawnQuery × alpha 个
            Note over P: 每个查询peer: 先 dialPeer 拨号
            P-->>Q: queryFn 发 RPC 成功
            Note over Q: 返回的新peer(heard)合并地址到 peerstore<br/>新peer转查询peer进入下一轮
            P-->>Q: 失败(拨号/RPC错误)
            Note over Q: peer 移出路由表,状态→PeerUnreachable
        end
    end
    Q-->>DHT: 返回 top-K 排序结果(peers+state)
    DHT-->>Caller: lookupWithFollowupResult2.4 重要数据结构// query represents a single DHT query.
// query 结构用于表示单个 DHT 查询
type query struct {
	// unique identifier for the lookup instance
	// 每个查询的唯一标识
	id uuid.UUID

	// target key for the lookup
	// 要查找的目标 key
	key string

	// the query context.
	// 上下文
	ctx context.Context

	// 当前 dht 对象
	dht *IpfsDHT

	// 查询设置中的种子节点
	seedPeers []peer.ID

	// peerTimes contains the duration of each successful query to a peer
	// 查询耗费的时间（成功的查询）
	peerTimes map[peer.ID]time.Duration

	// queryPeers is the set of peers known by this query and their respective states.
	// 查询已知的一组 peer 及其各自的状态
	queryPeers *qpeerset.QueryPeerset

	// terminated is set when the first worker thread encounters the termination condition.
	// 当第一个 Worker 符合终止条件时（stopFn 返回 false），则终止
	terminated bool

	// waitGroup ensures lookup does not end until all query goroutines complete.
	// 确保在所有查询协程完成之前查找不会结束
	waitGroup sync.WaitGroup

	// the function that will be used to query a single peer.
	// 将用于查询单个 peer 的函数
	queryFn queryFn

	// stopFn is used to determine if we should stop the WHOLE disjoint query.
	// 用于确定是否应停止整个查询
	stopFn stopFn
}// QueryPeerset 维护 Kademlia 异步查找的状态。查找状态是一组 peer，每个 peer 都标记有一个 peer 状态（queryPeerState）。
type QueryPeerset struct {
	// 正在搜索的 key
	key ks.Key

	// 所有已知的 peers
