	// 距 referredBy 的距离，用于排序
	distance   *big.Int
	state      PeerState
	referredBy peer.ID
}// queryUpdate：查询结果（传递到 chan），每个查询都有一个结果，会调用 updateState 更新
type queryUpdate struct {
