	queried     []peer.ID
	heard       []peer.ID
	unreachable []peer.ID

	queryDuration time.Duration
}2.5 主要函数解析runLookupWithFollowuprunLookupWithFollowup 是整个迭代查询的入口。调用 runQuery 启动迭代查询任务；从 runQuery 返回结果中将状态为 PeerHeard、PeerWaiting 的 peer 筛选出来。可能经过了几轮迭代查询后迭代退出条件已经满足，但已经收到了新的 peer，还没来得及调用 spawnQuery 发起任务，此时就会存在 PeerHeard 状态的 peer。这里的过滤 PeerWaiting 的 peer 应该是多余的。可能已经启动了 spawnQuery 还没查询完，但退出迭代条件已经满足。例如：10 个 query，有 3 个 query 已经查询成功，但其他 7 个 query 还没查询完，这时调用了 terminate 取消了 context，那么这 7 个 PeerWaiting 的 peer 状态就会变为 PeerUnreachable 或 PeerQueried。执行 runQuery 后不会再存在 PeerWaiting 状态的 peer，因为 run 中有执行 waitGroup.Wait 方法会等待所有查询结果，查询要么成功要么失败，就算取消 context 整个 queryPeer 方法也会照样执行（始终会将 queryUpdate 消息发回 chan）。如果没有状态为 PeerHeard、PeerWaiting 的 peer，则说明查询已经结束；如果 ctx 出错或 stopFn 条件满足也说明查询结束；对状态为 PeerHeard、PeerWaiting 的 peer 再做一次查询（启动协程，调用 queryFn），收尾工作，前面做到一半的工作不能不做完；从 chan doneCh 查询结果，有几个 peer 接收几次；如果 stopFn 满足条件或 ctx 完成则退出 doneCh 循环；如果 completed 仍为 false，则将 chan doneCh 的消息取完（阻塞等待查询完成）。func (dht *IpfsDHT) runLookupWithFollowup(ctx context.Context, target string, queryFn queryFn, stopFn stopFn) (*lookupWithFollowupResult, error) {
	// run the query
	lookupRes, err := dht.runQuery(ctx, target, queryFn, stopFn)
	if err != nil {
		return nil, err
	}

	queryPeers := make([]peer.ID, 0, len(lookupRes.peers))
	for i, p := range lookupRes.peers {
		if state := lookupRes.state[i]; state == qpeerset.PeerHeard || state == qpeerset.PeerWaiting {
			queryPeers = append(queryPeers, p)
		}
	}

	if len(queryPeers) == 0 {
		return lookupRes, nil
	}

	// return if the lookup has been externally stopped
	if ctx.Err() != nil || stopFn() {
		lookupRes.completed = false
		return lookupRes, nil
	}

	doneCh := make(chan struct{}, len(queryPeers))
	followUpCtx, cancelFollowUp := context.WithCancel(ctx)
	defer cancelFollowUp()
	for _, p := range queryPeers {
		qp := p
		go func() {
			_, _ = queryFn(followUpCtx, qp)
			doneCh <- struct{}{}
		}()
	}

	// wait for all queries to complete before returning, aborting ongoing queries if we've been externally stopped
	followupsCompleted := 0
processFollowUp:
	for i := 0; i < len(queryPeers); i++ {
		select {
		case <-doneCh:
			followupsCompleted++
			if stopFn() {
				cancelFollowUp()
				if i < len(queryPeers)-1 {
					lookupRes.completed = false
				}
				break processFollowUp
			}
		case <-ctx.Done():
			lookupRes.completed = false
			cancelFollowUp()
			break processFollowUp
		}
	}

	if !lookupRes.completed {
		for i := followupsCompleted; i < len(queryPeers); i++ {
			<-doneCh
		}
	}

	return lookupRes, nil
}runQuery调用 dht.routingTable.NearestPeers 获取 key 最近的 20 个 peer 作为种子 peer（也就是从本地路由表获取最近的 peer）；根据 key 和 20 个 seedpeer 构建 query；调用 query.run 等待结果（用 waitGroup 等待所有查询完成）；更新最有价值的 peer；构造查询结果并返回。func (dht *IpfsDHT) runQuery(ctx context.Context, target string, queryFn queryFn, stopFn stopFn) (*lookupWithFollowupResult, error) {
