	}

	res := q.constructLookupResult(targetKadID)
	return res, nil
}run启动 loop 循环前，将 20 个 seedpeer 放进了 queryUpdate 的 heard 集合中；启动 loop，监听 queryUpdate，发现有更新消息，调用 updateState 更新 peer 状态；进入 loop 后，首先进入 case update 分支，将 seedpeer 加入 queryPeers 集合（QueryPeerset）中，此时 seedpeer 的状态还是 heard；紧接着计算启动的 query 任务数量：maxNumQueriesToSpawn = alpha - q.queryPeers.NumWaiting()，alpha 默认为 10，第一次循环进来 waiting 数量为 0，maxNumQueriesToSpawn 的值此时为 10；调用 isReadyToTerminate 检查查询是否需要终止、生成新的 peer 集合。依次判断 stopFn/isStarvationTermination/isLookupTermination 条件是否满足，如果满足则直接退出 isReadyToTerminate，如果不满足退出条件则根据传入的 maxNumQueriesToSpawn 值，从 queryPeers 集合中取出状态为 PeerHeard 的节点（第一次循环进来 queryPeers 里有 20 个 seedpeer，那么这里只截取了前 10 个）；根据 isReadyToTerminate 的返回结果决定是否需要调用 terminate 方法终止迭代查询。如果 ready 为 true，则退出 run 方法（唯一的退出 run 出口），如果没有终止，则循环 qPeers 调用 spawnQuery 发起查询（qPeers 是上一步从 queryPeers 集合中截取的若干条记录）；waitGroup 等待所有 spawnQuery 任务完成。func (q *query) run() {
	pathCtx, cancelPath := context.WithCancel(q.ctx)
	defer cancelPath()

	alpha := q.dht.alpha

	ch := make(chan *queryUpdate, alpha)
	ch <- &queryUpdate{cause: q.dht.self, heard: q.seedPeers}

	// return only once all outstanding queries have completed.
	defer q.waitGroup.Wait()
	for {
		var cause peer.ID
		select {
		case update := <-ch:
			q.updateState(pathCtx, update)
			cause = update.cause
		case <-pathCtx.Done():
			q.terminate(pathCtx, cancelPath, LookupCancelled)
		}

		// calculate the maximum number of queries we could be spawning.
		// Note: NumWaiting will be updated in spawnQuery
		maxNumQueriesToSpawn := alpha - q.queryPeers.NumWaiting()

		// termination is triggered on end-of-lookup conditions or starvation of unused peers
		// it also returns the peers we should query next for a maximum of `maxNumQueriesToSpawn` peers.
		ready, reason, qPeers := q.isReadyToTerminate(pathCtx, maxNumQueriesToSpawn)
		if ready {
			q.terminate(pathCtx, cancelPath, reason)
		}

		if q.terminated {
			return
		}

		// try spawning the queries, if there are no available peers to query then we won't spawn them
		for _, p := range qPeers {
			q.spawnQuery(pathCtx, cause, p, ch)
		}
	}
