	return q.queryPeers.NumHeard() == 0 && q.queryPeers.NumWaiting() == 0
}GetClosestNInStates首先对 queryPeers 做一个排序，最近的排前面；遍历 queryPeers 将状态一致的 peer 加入 result。func (qp *QueryPeerset) GetClosestNInStates(n int, states ...PeerState) (result []peer.ID) {
	qp.sort()
	m := make(map[PeerState]struct{}, len(states))
	for i := range states {
		m[states[i]] = struct{}{}
	}

	for _, p := range qp.all {
		if _, ok := m[p.state]; ok {
			result = append(result, p.id)
		}
	}
	if len(result) >= n {
		return result[:n]
	}
	return result
}3. ChainMaker 网络模块集成实践来源：《2022-01-05 libp2p 分享-明超》（会议分享笔记，已补全为结构化说明）3.1 网络模块演进1.2.6网络模块基于 libp2p2.1.0自研网络（替换 libp2p）ChainMaker（长安链）网络模块在 1.2.6 及之前基于 libp2p，2.1.0 起自研网络。关键文件：libp2p_net.go —— libp2p 网络实现libp2p_host.go —— libp2p host（节点主机）封装架构要点：net 接口在 go-libp2p-core 中实现；为了支持国密（SM2/SM4），在 go.mod 中替换了 core 包（replace 为内部国密实现）；host 负责消息的发送/接收总装；peerId 等于 nodeid（libp2p 的 Peer ID 即 ChainMaker 的节点 ID）。3.2 连接控制与黑名单Q：如何将节点加入黑名单？
A：需要拿到节点的公钥，根据指定的算法，可以拿到 PeerId（Peer ID 由公钥哈希派生，黑名单按 Peer ID 维度生效）。过滤器限制接口的三个实现：黑名单过滤 —— 屏蔽指定 Peer ID 的连接memberStatusValidator 节点过滤器 —— 按节点成员状态校验链接总数限制 —— 控制节点最大连接数节点优先级的概念存在于 connManager（连接管理器）中。ConnSupervisor 与种子节点的链接：专门维护与种子节点的连接监督。拨号策略：斐波那契队列拨号方式 —— 从密集拨号到分散拨号，减少性能消耗（拨号失败后按斐波那契间隔退避重试，而非固定频率）。host 拨号相关概念：peerAddrInfos种子节点信息（地址簿）allConnected所有节点建立链接actuators每个链接都有一个 workertryTime尝试次数，默认 50 次（合理的链接次数）3.3 节点发现机制（libp2pDiscovery）基于 KadDHT（K 桶）：Gossip：随机询问其他节点是否能找到对应节点；分布式哈希桶：默认 16 个桶，每个桶默认 20 个节点信息，通过公共前缀（XOR 距离高位）放到对应的桶中；每隔 10 分钟刷新一遍所有桶；路由表本质是一个一维空间数组。讨论要点：5~9 是如何建立连接到的？—— 答：IpfsDHT（节点发现 + 迭代查询建立）节点中断后是否能够重新链接？—— 种子节点有重连机制，非种子节点没有（见第 4 章）3.4 消息处理与流message_handler_distributor：注册回调、注册链信息 chainId，按链 ID 分发消息；流池：管理节点间的流（stream），连接复用。4. 实战问题排查来源：《libp2p 遇到的问题》（ChainMaker 实战问题排查记录，已补全为结构化说明）4.1 节点连接问题问题 1：通过节点发现连接不稳定（都是共识节点的情况下）问题 2：节点连接状态不稳定 —— 一边连接正常，一边断开每个节点都会连接两个连接：一个是 127.0.0.1，一个是实际 id。问题 3：no stream can lot loord（偶发，压测时）作者说设置 100 个足够，但咱们默认就是 100，为什么在这个情景下会出现这个问题？（可能与流池扩容、swarm 拨号机制有关，见 4.4）4.2 节点 ID 映射问题问题 4：certId not mapping（map）节点维护 map<certId, nodeId>，为了兼容 certId 维护了这么一个 map。问题 5：field to did nodeid（修改 Gateway）Gateway 的作用：物理机（网关节点）。问题 6：node id not mapping节点维护 map<certId, nodeId>，为了兼容 certId 维护了这么一个 map。4.3 共识与出块问题问题 7：压测停节点时 TBFT 有问题，raft 没问题，dead block offtrigger 自己调自己的时候使用异步调用；底层 notify 通知机制：断开、连接时做什么，但是出问题的没有通知。不出块的原因：共识状态不一致，临界点卡共识合约合约结果不一致，导致的问题4.4 流池与拨号问题 8：流池扩容 dial backoffswarm 拨号机制底层频繁拨号；一个节点狂刷创建流。4.5 种子节点与非种子节点什么是种子节点和非种子节点？种子节点有重连机制，非种子节点没有。案例：1234 是种子节点，56789 是非种子节点，非种子节点连接不稳定；结论：节点发现逻辑冗余。4.6 测试案例记录case1税总分支TBFT本地文件存储case2税总分支TBFTNFS附录：原文出处1《libp2p DHT Kademlia 迭代查询》学无止境\golang\libp2p|CSDN 博文，源码级解析，第 1、2 章主体来源2《2022-01-05 libp2p 分享-明超》废寝忘食\Chainmaker\任务\2021-12-30_libp2p|会议分享笔记，第 3 章来源3《2022-02-07 学习 libp2p》同上KAD 算法速记（原文一句话），已补全为 1.1 节4《libp2p 遇到的问题》同上问题排查清单，第 4 章来源

来源：整合 6 张 Java 代码截图（懒汉、饿汉、双检锁、静态内部类、枚举）
主题：单例模式（创建型模式）的 5 种经典实现，对比与场景选型1. 单例模式基础1.1 概念定义：确保一个类只有一个实例，并提供全局访问点分类：设计模式 → 创建型模式核心代码：构造方法私有化（private），外部无法 new1.2 适用场景全局配置应用配置类日志Logger 单例数据库连接池Connection Pool缓存Cache Manager线程池、文件管理器-2. 五种实现方式2.1 懒汉式（线程不安全）特征：用时再建，懒加载public class LHan {
    private static LHan instance; // 懒汉式

private LHan() {} // 私有构造方法

public static LHan getInstance() {
    if (instance == null) {
        instance = new LHan();
    }
    return instance;
}

}延迟加载（lazy loading）线程不安全（多线程下可能创建多个实例）节省内存不推荐生产使用2.2 懒汉式（线程安全，加锁）public static synchronized LHan getInstance() {
    if (instance == null) {
        instance = new LHan();
    }
    return instance;
}线程安全每次 getInstance 都要加锁，性能差锁粒度太大2.3 饿汉式特征：类初始化时就建好，类加载即实例化public class EHan {
    private static EHan instance = new EHan(); // 饿汉式

private EHan() {} // 私有化构造方法

public static EHan getInstance() {
    return instance;
}

}线程安全（由 JVM 类加载机制保证）浪费内存（用不到也创建）实现简单无 lazy loading 效果2.4 双检锁（Double-Check Locking，DCL）特征：综合懒汉式 + 饿汉式优缺点，最常用public class DoubleCheck {

private static DoubleCheck instance;

private DoubleCheck() {}

public static DoubleCheck getInstance() {
    if (instance == null) {
        synchronized (DoubleCheck.class) {
            if (instance == null) {
                instance = new DoubleCheck();
            }
        }
    }
    return instance;
}

}关键细节：外层 if第一次判空，避免每次都进同步块（性能关键）synchronized保证线程安全内层 if防止多个线程同时通过外层 if 后重复创建注意：instance 字段应加 volatile 防止指令重排（JDK 1.5+ 才有正确语义）：private static volatile DoubleCheck instance;线程安全 + 高性能 + 延迟加载实现稍复杂；需理解 volatile2.5 静态内部类（推荐）public class Singleton {

private static class SingletonHolder {
    private static final Singleton INSTANCE = new Singleton();
}

private Singleton() {}

public static final Singleton getInstance() {
    return SingletonHolder.INSTANCE;
}

}核心原理：外部类加载时，静态内部类不会被加载（lazy loading）调用 getInstance() 才加载 SingletonHolder，此时才创建实例JVM 类加载机制保证线程安全（类初始化阶段加锁）线程安全 + 延迟加载 + 实现简洁只适用于静态域比双检锁更优雅实例域需要延迟初始化时不能用2.6 枚举（最佳实践）public enum Singleton {
    INSTANCE;
    public void anyMethod() {
        // 业务方法
    }
}实现最简洁不能延迟加载（枚举实例在类加载时创建）自动支持序列化机制不适合需要传参构造的场景绝对防止多次实例化（JVM 枚举机制）-线程安全（枚举实例天生单例）-Effective Java 作者 Joshua Bloch 推荐的实现方式。最简洁 + 最安全。3. 五种方式对比懒汉（不安全）❌✅最好⭐❌懒汉（synchronized）✅✅差⭐❌饿汉式✅❌好⭐❌双检锁✅✅好⭐⭐⭐❌（需 volatile）静态内部类✅✅好⭐⭐❌枚举✅❌最好⭐✅（JVM 保证）4. 场景选型决策树你的应用是否需要延迟加载？
├─ 不需要（启动时即用）
│   ├─ 涉及反序列化？ → ✅ 枚举（最佳）
│   └─ 普通场景       → ✅ 饿汉式
│
└─ 需要延迟加载
├─ 实例域（不是静态域）→ ✅ 双检锁
└─ 静态域            → ✅ 静态内部类
|||
|---|---|
|Spring Bean 单例|用容器（不需要自己实现）|
|工具类（无状态）|枚举 或 饿汉|
|重量级资源（DB 连接池）|双检锁 或 静态内部类|
|JDK / 框架内部单例|枚举（Joshua Bloch 推荐）|
|需要传参构造|双检锁（其他方式构造时无法传参）|5. 常见坑 & 注意事项5.1 反序列化破坏单例// 双检锁 / 饿汉：序列化 → 反序列化会创建新实例
// 解决：添加 readResolve 方法
private Object readResolve() {
    return instance;
}
// 枚举天然免疫（JVM 内部实现）5.2 反射破坏单例// 反射调用 private 构造器可绕过单例
// 解决：在构造器中防反射
private Singleton() {
    if (instance != null) {
        throw new RuntimeException("禁止反射创建");
    }
}
// 枚举天然免疫（不能通过反射创建枚举）5.3 指令重排（DCL 必须 volatile）// 错误：DCL 没有 volatile 可能返回未初始化的对象
private static DoubleCheck instance;

public static DoubleCheck getInstance() {
    if (instance == null) {              // 1
        synchronized (DoubleCheck.class) {
            if (instance == null) {
                instance = new DoubleCheck();  // 2 这一步可能被重排
            }
        }
    }
    return instance;                    // 3
}new 实际分 3 步：分配内存 → 初始化对象 → 赋值引用指令重排可能导致：分配内存 → 赋值引用 → 初始化对象此时其他线程看到 instance 非空，返回未初始化的对象 → NPE修复：private static volatile DoubleCheck instance;5.4 ClassLoader 破坏单例不同 ClassLoader 可能加载出不同的 Singleton 类 → 多个实例反序列化：自定义 readResolve 解决最佳实践：枚举 一劳永逸6. 知识延展6.1 Spring Bean 单例 vs 单例模式范围JVM 内一个类一个实例容器内一个 Bean 一个实例线程安全自己保证容器保证实现私有构造 + getInstance@Component + @Scope("singleton")6.2 相关模式工厂方法经常用单例实现工厂建造者内部 Builder 可以是单例享元多个"逻辑"对象共享，类似单例的扩展模板方法单例 + 模板方法 = 工具类附录 A：Java 代码速查懒汉式（不安全）public class LHan {
    private static LHan instance;
    private LHan() {}
    public static LHan getInstance() {
        if (instance == null) instance = new LHan();
        return instance;
    }
}饿汉式public class EHan {
    private static EHan instance = new EHan();
    private EHan() {}
    public static EHan getInstance() { return instance; }
}双检锁public class DoubleCheck {
    private static volatile DoubleCheck instance;
    private DoubleCheck() {}
    public static DoubleCheck getInstance() {
        if (instance == null) {
            synchronized (DoubleCheck.class) {
                if (instance == null) {
                    instance = new DoubleCheck();
                }
