主题：红黑树（Red-Black Tree）的定义、5 条性质、配图解读、平衡原理与 Go 语言实现一、简介红黑树（Red Black Tree）是一种自平衡二叉查找树，在计算机科学中用于实现关联数组（如 std::map / TreeMap）。起源：1972 年由 Rudolf Bayer 发明，最初称「平衡二叉 B 树（symmetric binary B-trees）」；1978 年由 Leo J. Guibas 和 Robert Sedgewick 修改为现今的「红黑树」。与 AVL 关系：红黑树是 AVL 树（严格平衡二叉树）的特化 —— 通过在插入/删除时做特定旋转和着色保持平衡。复杂度：查找、插入、删除最坏时间均为 O(log n)（n = 节点数），是实践中高效的平衡树方案。二、5 条性质1节点颜色节点是红色或黑色2根节点根节点是黑色3叶子所有叶子（NIL 节点）都是黑色4红色节点的子节点每个红色节点的两个子节点都是黑色（从任一叶子到根的路径上不能有两个连续的红色节点）5黑色高度从任一节点到其每个叶子的所有路径包含相同数目的黑色节点关键推论：由性质 4 + 5 可得：从根到叶子的最长可能路径 ≤ 最短可能路径的 2 倍最短路径：全黑节点；最长路径：红黑交替树大致平衡 → 查找/插入/删除的高度上限可控 → 最坏情况也高效红黑树的只读操作（查找）与普通二叉查找树完全相同；插入和删除需要额外的旋转 + 着色来恢复性质。三、配图与图解图内容文字描述（节点 = 值(颜色)，NIL 视为黑色叶子）：                13(B)
              /       \
           8(R)       17(R)
          /   \       /    \
        1(B) 11(B) 15(B)  25(B)
              /              \
           6(R)             22(R)
                              \
                             27(R)层级与性质验证：13 → 8 → 1 → NIL313 → 8 → 1 → NIL313 → 8 → 11 → NIL313 → 8 → 11 → 6 → NIL313 → 17 → 15 → NIL313 → 17 → 25 → NIL313 → 17 → 25 → 22 → NIL313 → 17 → 25 → 22 → 27 → NIL3所有路径黑色高度一致 = 3 ✓四、平衡原理保持平衡的两类操作：旋转（左旋 / 右旋）改变局部结构，转移子树归属插入/删除后父子链方向不满足红黑性质着色 / 变色改变节点颜色，满足性质 4、5父与叔都为红 → 父叔变黑、祖父变红，向上递归修复经典修复分支（删除时最复杂）：Case 1（兄弟为红）：父染红、兄染黑，旋转到兄弟侧 → 转 Case 4/5/6Case 2/3（父黑、兄黑、子全黑）：兄染红，修复点上移（黑高减一向上传递）Case 4（父红、兄黑、兄子全黑）：父染黑、兄染红，结束Case 5（兄黑、远侄红）：转为 Case 6Case 6（兄黑、远侄红）：旋转 + 重新染色，一轮结束推荐阅读：红黑树是如何保持平衡的 — zzt-lovelinlin五、Go 实现以下实现转载自 freedbg — CSDN 博客，并修复了原文中两处 b.br() typo（应为 n.br()），保证代码可编译。整体结构如下：node.l / r / p左 / 右 / 父指针node.v节点值node.c颜色（false = 红，true = 黑）Tree.root / last / size树根、最近插入节点、节点数rotateL / rotateR左 / 右旋Insert / insertB / inserCase插入（BST 插入 + 插入后修复）tdelete / deleteR / fix2删除（替换为前驱/后继 + 删除后修复）printT / printTree控制台按层打印（带颜色）package main

import "fmt"

var data = []int{6, 5, 3, 1, 8, 7, 2, 4, 9, 0, 3}

func main() {
	fmt.Println("red-black-tree")
	tree := NewTree()
	for _, v := range data {
		tree.insertB(v)
	}
	tree.tdelete(tree.root, 2)
	printT(tree.root)
}

type node struct {
	l, r, p *node
	v       int
	c       bool // false = red, true = black
}

type Tree struct {
	root *node
	last *node
	size int
}

func NewTree() *Tree { return &Tree{} }

// ===== 辅助：祖父 / 叔父 / 兄弟 =====

func (n *node) getGp() *node {
	if n.p == nil {
		return nil
	}
	if n.p.p == nil {
		return nil
	}
	return n.p.p
}

func (n *node) getUn() *node {
	if n.getGp() == nil {
		return nil
	}
	if n.p == n.getGp().l {
		return n.getGp().r
	}
	return n.getGp().l
}

func (n *node) br() *node {
	if n.p.l == n {
		return n.r
	}
	return n.l
}

// ===== 旋转 =====

func (tree *Tree) rotateR(n *node) {
	gp := n.getGp()
	p := n.p
	r := n.r

	n.r = p
	n.p = gp

	if p != nil {
		p.p = n
		p.l = r
		if r != nil {
			r.p = p
		}
	}
	if tree.root == p {
		tree.root = n
	}
	if gp != nil {
		if gp.l == p {
			gp.l = n
		} else {
			gp.r = n
		}
	}
}

func (tree *Tree) rotateL(n *node) {
	gp := n.getGp()
	p := n.p
	l := n.l

	n.l = p
	n.p = gp

	if p != nil {
		p.p = n
		p.r = l
		if l != nil {
			l.p = p
		}
	}
	if tree.root == p {
		tree.root = n
	}
	if gp != nil {
		if gp.l == p {
			gp.l = n
		} else {
			gp.r = n
		}
	}
}

// ===== 插入 =====

func (tree *Tree) insertB(v int) {
	if tree.root == nil {
		tree.root = &node{v: v, c: true}
		tree.size++
		return
	}

	if v < tree.root.v {
		if tree.Insert(&tree.root.l, v, tree.root) {
			tree.size++
			tree.inserCase(tree.last)
		}
	}
	if v > tree.root.v {
		if tree.Insert(&tree.root.r, v, tree.root) {
			tree.size++
			tree.inserCase(tree.last)
		}
	}
	printT(tree.root)
}

func (tree *Tree) Insert(n **node, v int, fa *node) bool {
	pn := *n
	if pn == nil {
		*n = &node{v: v, p: fa}
		tree.last = *n
		return true
	}
	if v > pn.v {
		return tree.Insert(&pn.r, v, pn)
	}
	if v < pn.v {
		return tree.Insert(&pn.l, v, pn)
	}
	return false // equal: not inserted
}

func (tree *Tree) inserCase(n *node) {
	if n.p == nil { // 根节点染黑
		n.c = true
		tree.root = n
		return
	}
	if n.p.c == false { // 父为红才需要修复
		if n.getUn() != nil && n.getUn().c == false {
			// 叔为红：父叔染黑，祖父染红，向上递归
			n.p.c = true
			n.getUn().c = true
			n.getGp().c = false
			tree.inserCase(n.getGp())
			return
		}
		// 叔为黑或 NIL：通过旋转 + 染色修复
		if n == n.p.r && n.p == n.getGp().l {
			tree.rotateL(n)
			tree.rotateR(n)
			n.c = true
			n.l.c, n.r.c = false, false
		} else if n == n.p.l && n.p == n.getGp().r {
			tree.rotateR(n)
			tree.rotateL(n)
			n.c = true
			n.l.c, n.r.c = false, false
		} else if n == n.p.l && n.p == n.getGp().l {
			n.p.c = true
			n.getGp().c = false
			tree.rotateR(n.p)
		} else if n == n.p.r && n.p == n.getGp().r {
			n.p.c = true
			n.getGp().c = false
			tree.rotateL(n.p)
		}
	}
}

// ===== 删除 =====

func (tree *Tree) tdelete(n *node, v int) {
	if n == nil {
		return
	}
	if v < n.v {
		tree.tdelete(n.l, v)
		return
	}
	if v > n.v {
		tree.tdelete(n.r, v)
		return
	}
	// v == n.v
	if n.l != nil && n.r != nil {
		mn := tree.findMax(n.l) // 左子树最大节点作为替换
		n.v = mn.v
		if tree.deleteR(mn) {
			tree.size--
		}
		return
	}
	if tree.deleteR(n) {
		tree.size--
	}
}

func (tree *Tree) findMax(n *node) *node {
	for n.r != nil {
		n = n.r
	}
	return n
}

func (tree *Tree) deleteR(n *node) bool {
	red, black := false, true

	// case 1: 删除的是根（无父 + 无子）
	if n.l == nil && n.r == nil && n.p == nil {
		tree.root = nil
		return true
	}

	var child *node
	if n.l != nil {
		child = n.l
	} else {
		child = n.r
	}

	// case 2: 删除后 child 升为新根
	if n.p == nil {
		child.p = nil
		tree.root = child
		child.c = black
		return true
	}

	if n.p.l == n {
		n.p.l = child
	} else {
		n.p.r = child
	}
	if child != nil {
		child.p = n.p
	}

	// 删除黑色节点才需要修复（少了一个黑高）
	if n.c == black {
		if child != nil && child.c == red {
			child.c = black // case: 红孩子顶替黑色被删节点
		} else {
			tree.fix2(n) // n 作为「双重黑」位置继续修复
		}
	}
	_ = red
	return true
}

// n 作为「双重黑」位置（黑高不平衡）的修复
func (tree *Tree) fix2(n *node) {
	black := true

	// case 1: 已到根
	if n.p == nil {
		n.c = black
		return
	}

	// case 2: 兄弟为红（旋转后转为 case 4/5/6）
	if n.br().c == false && n.p.c == black {
		n.p.c = false
		n.br().c = black
		if n == n.p.l {
			tree.rotateL(n.br())
		} else {
			tree.rotateR(n.br())
		}
	}

	// case 3: 父黑 + 兄黑 + 兄子全黑（黑高上移）
	if n.p.c == black && n.br().c == black && n.br().l == nil && n.br().r == nil {
		n.br().c = false
		tree.fix2(n.p)
		return
	}

	// case 4: 父红 + 兄黑 + 兄子全黑
	if n.p.c == false && n.br().c == black && n.br().l == nil && n.br().r == nil {
		n.p.c = black
		n.br().c = false
		return
	}

	// case 5: 兄黑 + 「近侄」红（先转成 case 6）
	if n.br().c == black {
		if n.br().l != nil && n.br().r == nil && n == n.p.l {
			n.br().c = false
			n.br().l.c = black
			tree.rotateR(n.br().l)
		} else if n.br().r != nil && n.br().l == nil && n == n.p.r {
			n.br().c = false
			n.br().r.c = black
			tree.rotateL(n.br().r)
		}
	}

	// case 6: 兄黑 + 「远侄」红（一轮修复结束）
	if n.br().c == black && n.br().r != nil && n == n.p.l {
		n.br().c = n.p.c
		tree.rotateL(n.br())
		n.p.c = black
		n.getGp().r.c = black
		return
	}
	if n.br().c == black && n.br().l != nil && n == n.p.r {
		n.br().c = n.p.c
		tree.rotateR(n.br())
		n.p.c = black
		n.getGp().l.c = black
		return
	}
}

