		fmt.Println("L", i, s)
	}
}

func printTree(tree *node, i int, n string) {
	i++
	str := " "
	for k := i; k < 9; k++ {
		str += "-"
	}
	color := "\033[41;37m" // 红底白字
	if tree.c {
		color = "\033[40;37m" // 黑底白字
	}
	tmp := fmt.Sprintf("%s [%d] %s%s%s", str, tree.v, color, n, "\033[0m")
	fstr[i] += tmp
	if tree.l != nil {
		printTree(tree.l, i, "L"+itoa(tree.v))
	}
	if tree.r != nil {
		printTree(tree.r, i, "R"+itoa(tree.v))
	}
}

