    numStack := []int{}      // 数字栈
    strStack := []string{}   // 字符串栈
    num := 0
    cur := ""
    for _, c := range s {
        if c >= '0' && c <= '9' {
            num = num*10 + int(c-'0')
        } else if c == '[' {
            numStack = append(numStack, num)
            strStack = append(strStack, cur)
            num = 0
            cur = ""
        } else if c == ']' {
            n := numStack[len(numStack)-1]
            numStack = numStack[:len(numStack)-1]
            prev := strStack[len(strStack)-1]
            strStack = strStack[:len(strStack)-1]
            cur = prev + strings.Repeat(cur, n)
        } else {
            cur += string(c)
        }
    }
    return cur
}3.2 链表链表翻转反转单链表O(n)奇偶节点分离奇数节点在前、偶数节点在后，保持相对顺序O(n) 空间 O(1)奇偶分离 LeetCode 328：func oddEvenList(head *ListNode) *ListNode {
    if head == nil || head.Next == nil {
        return head
    }
    odd, even := head, head.Next
    evenHead := even
    for even != nil && even.Next != nil {
        odd.Next = even.Next
        odd = odd.Next
        even.Next = odd.Next
        even = even.Next
    }
    odd.Next = evenHead
    return head
}3.3 数组操作合并有序数组经典归并排序的子步骤技巧：从后往前填充（避免额外空间）串中关键字 + 联系方式识别（机器学习/NLP）输入：自然语言文本（含"微信""QQ"等关键字 + 数字串）
输出：每个字符的标签0无关变量1关键字开头2关键字中间/末尾3串的开头4串的中间/末尾示例：输入："想知道如果提高王者荣耀水平，上分把妹不是梦，加微信：17252sugats78，加QQ：34676328889"标签：[..., 1, 2, 0, 3, 4, 4, ...]输出：关键字 ['微信', 'QQ']，串 ['17252sugats78', '34676328889']这类问题本质是 BIOES 标注（NLP 序列标注）最少 bug 选码农问题：n 个码农，每天 s[i] 行代码 + b[i] 个 bug；项目每天至少 m 行代码；选最少 bug 的集合本质：0-1 背包问题的变形（约束 ≥ m，求最小代价）解法：DP：dp[i][j] = 前 i 个码农完成 j 行代码的最小 bug 数状态转移：dp[i][j] = min(dp[i-1][j], dp[i-1][j-s[i]] + b[i])答案：min(dp[n][j]) for j in [m, sum(s)]时间复杂度：O(n × sum(s))，可优化4. Go 实战编程题4.1 字符串操作// 全局变量
